CREATE TABLE "activity_entries" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "created_at" timestamptz NOT NULL, "updated_at" timestamptz NOT NULL, "actor" character varying NOT NULL, "action" character varying NOT NULL, "object_kind" character varying NOT NULL, "object_id" bigint NOT NULL, "object_name" character varying NULL, PRIMARY KEY ("id"));
CREATE INDEX "activityentry_actor" ON "activity_entries" ("actor");
CREATE INDEX "activityentry_object_kind_object_id" ON "activity_entries" ("object_kind", "object_id");
